import json,pathlib,sys
import rawpy,numpy as np
root=pathlib.Path(__file__).resolve().parent.parent;n=int(sys.argv[1]);prefix=f'{n:02d}';d=json.loads((root/'results'/f'{prefix}_decode.json').read_text());inv=json.loads((root/'inventory.json').read_text());a=json.loads((root/'results'/f'{prefix}_analysis.json').read_text())
